# Simple cosmological calculator class
class SimpleCosmology:
    def __init__(self, H0=H0, gamma=gamma):
        self.H0 = H0
        self.gamma = gamma

    def Hubble(self, z):
        return self.H0 * (1 + z) ** self.gamma

    def scale_factor(self, z):
        # Scale factor a(z) = (1+z)^{1/gamma}
        return (1 + z) ** (1.0 / self.gamma)

    def luminosity_distance(self, z):
